using System;
using System.Collections.Generic;
using System.Linq;

// PROGRAM: Simulasi Cara Kerja Mapper Dapper Berbasis Anonymous Type Parameters
public record AccountRecord(string Id, string Name, decimal Balance);

public class FakeDapperConnection
{
    private readonly List<AccountRecord> _db = new()
    {
        new("ACC-1", "Budi", 500_000m),
        new("ACC-2", "Siti", 1_500_000m),
        new("ACC-3", "Ahmad", 2_000_000m)
    };

    // Simulasi QueryAsync Dapper
    public IEnumerable<AccountRecord> Query(string sql, object param)
    {
        Console.WriteLine($"[DAPPER SQL EXEC] {sql}");
        // Ekstraksi parameter anonim via reflection dinamis yang di-cache
        var prop = param.GetType().GetProperty("MinBalance");
        decimal min = prop != null ? (decimal)prop.GetValue(param)! : 0m;

        return _db.Where(a => a.Balance >= min);
    }
}

public class Program
{
    public static void Main()
    {
        var conn = new FakeDapperConnection();
        var results = conn.Query("SELECT * FROM Accounts WHERE Balance >= @MinBalance", new { MinBalance = 1_000_000m });

        Console.WriteLine("\nHasil Pemetaan Dapper:");
        foreach (var acc in results)
        {
            Console.WriteLine($" - {acc.Name,-10} | Saldo: Rp {acc.Balance:N0}");
        }
    }
}

