using System;
using System.Collections.Generic;
using System.Reflection;

public class MiniDapperParamMapper
{
    public static Dictionary<string, object?> ExtractDapperParameters(object? parameters)
    {
        var result = new Dictionary<string, object?>(StringComparer.OrdinalIgnoreCase);
        if (parameters == null) return result;

        var props = parameters.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance);
        foreach (var p in props)
        {
            result[$"@{p.Name}"] = p.GetValue(parameters);
        }

        return result;
    }

    public static void Main()
    {
        var p = new { AccountId = "ACC-01", Amount = 50000m };
        var dict = ExtractDapperParameters(p);
        foreach (var kv in dict) Console.WriteLine($"{kv.Key} = {kv.Value}");
    }
}
